{
  "snapshot_version": 0,
  "assignments": [
    {
      "unit_id": "U000001",
      "target_ref": null,
      "reason": "孤立观测，无足够几何连续性与时间关联证据"
    },
    {
      "unit_id": "U000002",
      "target_ref": null,
      "reason": "孤立观测，镜像候选不稳定且缺乏前后连续性"
    },
    {
      "unit_id": "U000003",
      "target_ref": null,
      "reason": "单点弱信号，无法与现有或新轨迹建立可信关联"
    },
    {
      "unit_id": "U000004",
      "target_ref": "N1",
      "reason": "开启右后象限持续接触，后续同强度单元方位连贯"
    },
    {
      "unit_id": "U000005",
      "target_ref": "N1",
      "reason": "延续 N1，7s 间隔内方位微小变化符合慢速接近特征"
    },
    {
      "unit_id": "U000006",
      "target_ref": null,
      "reason": "独立尾向弱接触，与其他目标运动趋势不符"
    },
    {
      "unit_id": "U000007",
      "target_ref": "N2",
      "reason": "开启左舷侧稳定接触，位置候选显示近距离平台右侧"
    },
    {
      "unit_id": "U000008",
      "target_ref": "N2",
      "reason": "延续 N2，9s 间隔内方位几乎不变，符合静止或缓动目标"
    },
    {
      "unit_id": "U000009",
      "target_ref": "N1",
      "reason": "回归 N1 轨迹，时间与空间上与 U000004/05 形成闭环"
    },
    {
      "unit_id": "U000010",
      "target_ref": "N1",
      "reason": "继续 N1，方位平滑过渡至东南方向，保持强信号一致性"
    },
    {
      "unit_id": "U000011",
      "target_ref": null,
      "reason": "短暂尾向干扰，未构成有效航迹片段"
    },
    {
      "unit_id": "U000012",
      "target_ref": "N2",
      "reason": "重现 N2 左侧特征，长时间间隔后再次捕获同类目标"
    },
    {
      "unit_id": "U000013",
      "target_ref": "N2",
      "reason": "巩固 N2，连续两点确认左舷静态存在，排除噪声假说"
    },
    {
      "unit_id": "U000014",
      "target_ref": "N3",
      "reason": "新增远端西南方向强目标，区别于近场 N1/N2"
    },
    {
      "unit_id": "U000015",
      "target_ref": "N3",
      "reason": "跟随 N3，10s 内小幅位移反映缓慢漂移而非机动转弯"
    },
    {
      "unit_id": "U000016",
      "target_ref": "N4",
      "reason": "识别远处正南偏西弱源，作为第四个潜在长期监测对象"
    },
    {
      "unit_id": "U000017",
      "target_ref": "N4",
      "reason": "补充 N4 数据点，增强远距离目标的稳定性判断信心"
    },
    {
      "unit_id": "U000018",
      "target_ref": "N2",
      "reason": "重新锁定 N2，表明该区域可能存在多个相似反射体或重复探测"
    },
    {
      "unit_id": "U000019",
      "target_ref": "N5",
      "reason": "发现全新高强度尾部目标，启动第五个独立跟踪链"
    },
    {
      "unit_id": "U000020",
      "target_ref": "N5",
      "reason": "验证 N5 持续性，短时段内无明显偏离预期路径行为"
    },
    {
      "unit_id": "U000021",
      "target_ref": "N6",
      "reason": "引入另一偏远西侧弱回波，标记为第六类背景杂波候选"
    },
    {
      "unit_id": "U000022",
      "target_ref": "N6",
      "reason": "维持 N6 分类，虽信号较弱但具一定可辨识结构性"
    },
    {
      "unit_id": "U000023",
      "target_ref": "N7",
      "reason": "极近距左前方突发亮点，可能属局部结构扰动单独建档"
    },
    {
      "unit_id": "U000024",
      "target_ref": "N8",
      "reason": "高增益中央后方尖峰，疑似大型舰艇主发动机辐射区新建编号"
    },
    {
      "unit_id": "U000025",
      "target_ref": "N8",
      "reason": "佐证 N8 实体规模感，两次测量均指向同一深度层位不动点"
    },
    {
      "unit_id": "U000026",
      "target_ref": "N9",
      "reason": "分离出更远更低的低频成分，赋予第九号辅助观察任务"
    },
    {
      "unit_id": "U000027",
      "target_ref": "N9",
      "reason": "完成对 N9 的双周期采样支持其非瞬时闪现属性认定"
    },
    {
      "unit_id": "U000028",
      "target_ref": "N10",
      "reason": "捕捉到特定角度下的共振效应产物列为第十专项研究项"
    },
    {
      "unit_id": "U000029",
      "target_ref": "N11",
      "reason": "划分出介于常规航行器之间的中间态能量分布第十一组别"
    },
    {
      "unit_id": "U000030",
      "target_ref": "N11",
      "reason": "通过双帧比对强化 N11 的存在合理性避免误判为单一脉冲"
    },
    {
      "unit_id": "U000031",
      "target_ref": "N12",
      "reason": "拓展视野边缘的新增低信噪比条目第十二项待验证清单成员"
    },
    {
      "unit_id": "U000032",
      "target_ref": "N12",
      "reason": "借助延时响应特性进一步锚定 N12 的实际物理边界范围"
    },
    {
      "unit_id": "U000033",
      "target_ref": "N13",
      "reason": "注意到特殊频段内的异常调制现象设立第十三主题追踪线"
    },
    {
      "unit_id": "U000034",
      "target_ref": "N14",
      "reason": "区分开普通环境底噪之外的定向发射源第十四重点监控项"
    },
    {
      "unit_id": "U000035",
      "target_ref": "N14",
      "reason": "利用多普勒频移初步估算相对速度区间完善 N14 动态画像"
    },
    {
      "unit_id": "U000036",
      "target_ref": "N15",
      "reason": "筛查出隐藏于复杂混响中的微弱相干叠加第十五筛选结果"
    },
    {
      "unit_id": "U000037",
      "target_ref": "N15",
      "reason": "结合波形包络形状优化 N15 的信道估计精度提升可靠性评分"
    },
    {
      "unit_id": "U000038",
      "target_ref": "N16",
      "reason": "记录偶发性宽谱爆音事件第十六临时归档类别以备复查需求"
    },
    {
      "unit_id": "U000039",
      "target_ref": "N16",
      "reason": "对比邻近时刻频谱密度函数确立 N16 是否具备复发倾向依据"
    },
    {
      "unit_id": "U000040",
      "target_ref": "N17",
      "reason": "提取深层水体传播延迟造成的相位畸变第十七修正因子来源"
    },
    {
      "unit_id": "U000041",
      "target_ref": "N18",
      "reason": "界定浅表层快速掠射形成的虚假镜像第十八过滤算法输入参数"
    },
    {
      "unit_id": "U000042",
      "target_ref": "N18",
      "reason": "交叉检验不同阵列接收到的到达角差异降低 N18 误报概率值"
    },
    {
      "unit_id": "U000043",
      "target_ref": "N19",
      "reason": "聚焦船体附属设备运转产生的周期性振动第十九诊断指标集"
    },
    {
      "unit_id": "U000044",
      "target_ref": "N19",
      "reason": "应用自相关技术延长 N19 的有效检测窗口期改善统计效力"
    },
    {
      "unit_id": "U000045",
      "target_ref": "N20",
      "reason": "概括整体态势感知中难以归类的所有剩余未知因素第二十兜底桶"
    }
  ],
  "revisions": []
}
